import { describe, it, expect, vi, beforeEach } from 'vitest';
import { SupabaseClient } from '@supabase/supabase-js';
import { repo } from '../repo';

describe('appendChangeLog', () => {
  let mockClient: SupabaseClient;

  beforeEach(() => {
    mockClient = {
      from: vi.fn().mockReturnValue({
        insert: vi.fn().mockReturnValue({
          error: vi.fn().mockReturnValue(null),
          data: [],
        }),
      }),
    } as any;
  });

  it('should not include id in insert payload', async () => {
    const mockInsert = vi.fn();
    mockClient.from('changelog').insert = mockInsert;

    await repo.appendChangeLog(mockClient, { 
      campaign_id: 'campaign-123',
      action: 'create',
      detail: 'test detail'
    });

    expect(mockInsert).toHaveBeenCalledWith({
      campaign_id: 'campaign-123',
      action: 'create',
      detail: 'test detail'
    });
  });

  it('should propagate insert errors', async () => {
    const error = new Error('Insert failed');
    const mockInsert = vi.fn().mockRejectedValue(error);
    mockClient.from('changelog').insert = mockInsert;

    await expect(repo.appendChangeLog(mockClient, {
      campaign_id: 'campaign-123',
      action: 'create',
      detail: 'test detail'
    })).rejects.toThrow(error);
  });
});

